<?php require_once 'config.php';$pageTitle='Explore courses';$courses=[];$enrolled=[];try{$courses=db()->query("SELECT c.*,u.name trainer_name FROM courses c LEFT JOIN users u ON c.trainer_id=u.id WHERE c.status='published' ORDER BY c.created_at DESC")->fetchAll();if(logged_in()){$s=db()->prepare('SELECT course_id FROM enrollments WHERE user_id=?');$s->execute([current_user()['id']]);$enrolled=array_column($s->fetchAll(),'course_id');}}catch(Throwable $e){}require 'includes/header.php'; ?>
<section class="page-heading"><span class="eyebrow">FIND YOUR NEXT SKILL</span><h1>Explore <em>courses.</em></h1><p>Learning paths to help you build confidence, capability and practical knowledge.</p><div class="search-wrap"><span>⌕</span><input id="courseSearch" placeholder="Search courses or categories..." aria-label="Search courses"></div></section><section class="section"><div class="course-grid" id="courseGrid"><?php foreach($courses as $c): ?><article class="course-card searchable-course" data-search="<?= e(strtolower($c['title'].' '.$c['category'].' '.$c['description'])) ?>"><div class="course-cover cover-<?= e($c['category'] ?: 'general') ?>"><span><?= e($c['icon'] ?: '✦') ?></span><small><?= e($c['category'] ?: 'Learning path') ?></small></div><div class="course-content"><h3><?= e($c['title']) ?></h3><p><?= e(mb_strimwidth($c['description']??'',0,130,'…')) ?></p><div class="course-meta"><span>By <?= e($c['trainer_name']??'Capacity Connect') ?></span><a href="course.php?id=<?= (int)$c['id'] ?>">View details →</a></div><?php if(in_array($c['id'],$enrolled)): ?><span class="status-pill">✓ Enrolled</span><?php endif; ?></div></article><?php endforeach; ?><?php if(!$courses): ?><div class="empty-state"><span>✦</span><h3>No courses published yet</h3><p>Once a trainer publishes a course, it will be available here.</p><?php if(logged_in()&&in_array(current_user()['role'],['trainer','admin'])):?><a class="btn btn-primary" href="trainer.php">Create a course</a><?php endif; ?></div><?php endif; ?></div><p id="noResults" class="muted hidden">No courses match your search.</p></section><?php require 'includes/footer.php'; ?>
